package local.lito381.server;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Pure capacity and unbound actual queue/drainer contracts; no player, Hub, socket, SQL or BATTLE fixture. */
public final class SourceCubeNpcQueuePlan {
 static int cases;static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);cases++;}
 static CombatNpcDamageQueue.Event event(long id,CombatWorldCommit.Plan plan){return new CombatNpcDamageQueue.Event(0,0,null,id,0,10,0,"source-cube-effect","","",plan);}
 static CombatWorldCommit.Plan originalProc()throws Exception{var ctor=Class.forName("local.lito381.server.NativeProcHealingEncounter$Plan").getDeclaredConstructors()[0];ctor.setAccessible(true);return(CombatWorldCommit.Plan)ctor.newInstance(new NativeCombatAttacker.Ref(3,20,new Object(),0,null,7,-1,-1),null,1,new Object(),null);}
 public static void main(String[]args)throws Exception{
  var counter=new AtomicLong();check(NativeSourcePendingAdmission.reserve(counter,2)&&counter.get()==1,"first shared slot reserved");check(NativeSourcePendingAdmission.reserve(counter,2)&&counter.get()==2,"second shared slot reserved");check(!NativeSourcePendingAdmission.reserve(counter,2)&&counter.get()==2,"exact shared capacity rejected without overshoot");counter.decrementAndGet();check(NativeSourcePendingAdmission.reserve(counter,2)&&counter.get()==2,"released slot can be reserved again");
  check(!NativeSourcePendingAdmission.reserve(new AtomicLong(),0),"zero limit rejects");check(!NativeSourcePendingAdmission.reserve(new AtomicLong(-1),10),"invalid negative pending state is not silently repaired");var maximum=new AtomicLong(Long.MAX_VALUE-1);check(NativeSourcePendingAdmission.reserve(maximum,Long.MAX_VALUE)&&maximum.get()==Long.MAX_VALUE,"last long slot has no overflow");check(!NativeSourcePendingAdmission.reserve(maximum,Long.MAX_VALUE),"full long capacity cannot wrap");
  var rollback=new AtomicLong();NativeSourcePendingAdmission.reserve(rollback,1);boolean rejected=false;try{NativeSourcePendingAdmission.add(new ArrayDeque<>(),null,rollback);}catch(NullPointerException expected){rejected=true;}check(rejected&&rollback.get()==0,"failed original PC publication releases its newly reserved slot");
  var deque=new ArrayDeque<Object>();var item=new Object();NativeSourcePendingAdmission.reserve(rollback,1);check(NativeSourcePendingAdmission.add(deque,item,rollback)&&deque.peek()==item&&rollback.get()==1,"successful original publication retains exactly one slot");rollback.decrementAndGet();
  var racing=new AtomicLong();var granted=new AtomicLong();var error=new AtomicReference<Throwable>();var start=new CountDownLatch(1);var threads=new ArrayList<Thread>();for(int t=0;t<16;t++){var worker=new Thread(()->{try{start.await();for(int n=0;n<4096;n++)if(NativeSourcePendingAdmission.reserve(racing,511))granted.incrementAndGet();}catch(Throwable failure){error.compareAndSet(null,failure);}},"pure-capacity-test-"+t);threads.add(worker);worker.start();}start.countDown();for(var worker:threads)worker.join(10000);check(error.get()==null&&threads.stream().noneMatch(Thread::isAlive),"bounded pure CAS test threads settle");check(racing.get()==511&&granted.get()==511,"concurrent PC/NPC-style callers share one strict primitive cap");
  check(!NativeSourcePendingAdmission.offer(null,null,null),"missing actual queue/event cannot create lifetime authority");
  check(!NativeSourceCubeNpcQueue.ticket(null),"null is not a cube ticket");var marker=new NativeSourceCubeNpcQueue.Ticket(null,null);var a=event(1,marker);var b=event(2,null);check(NativeSourceCubeNpcQueue.ticket(a)&&!NativeSourceCubeNpcQueue.ticket(b),"typed cube plan remains distinct from ordinary envelope");
  check(!NativeSourceCubeNpcQueue.envelope(a,null),"unbound ticket cannot grant HP authority");check(!NativeSourceCubeNpcQueue.consume(null,null,b),"ordinary plan keeps the original drainer path");check(NativeSourceCubeNpcQueue.consume(null,null,a),"unbound typed ticket is consumed as a safe drop, not a player substitution");NativeSourceCubeNpcQueue.producerFinished(null);
  long baseline=CombatNpcDamageQueue.pending();var queue=new CombatNpcDamageQueue.Queue();check(queue.offer(a)&&queue.offer(b)&&queue.pending()==2,"actual existing FIFO admits two envelope objects");check(queue.start()&&!queue.start(),"only one actual drainer owns dispatch");check(queue.claim()==a,"first event retains FIFO identity");boolean overlap=false;try{queue.claim();}catch(IllegalStateException expected){overlap=true;}check(overlap,"existing overlapping-commit fence retained");queue.complete(a);check(queue.pending()==1&&queue.claim()==b,"original completion exposes the next event in order");queue.complete(b);check(queue.claim()==null&&queue.pending()==0,"original drain settles and becomes idle");check(CombatNpcDamageQueue.pending()==baseline,"actual queue global count returns to its baseline");
  var proc=event(3,originalProc());var mixed=new CombatNpcDamageQueue.Queue();mixed.offer(a);mixed.offer(proc);mixed.offer(event(4,marker));mixed.start();NativeProcHealingEncounter.nativeSourceCubeDrain(null,mixed).run();check(mixed.pending()==0&&mixed.claim()==null,"actual original drainer settles mixed cube/old-proc metadata without a foreign-plan failure");check(CombatNpcDamageQueue.pending()==baseline,"mixed drainer completes every actual queue slot exactly once");
  var dropped=new CombatNpcDamageQueue.Queue();dropped.offer(a);dropped.offer(b);synchronized(dropped){NativeSourceCubeNpcQueue.clearing(dropped);}dropped.clear(false);check(dropped.pending()==0&&!dropped.closed(),"nonterminal original clear drops pending tail without closing compatibility queue");check(dropped.offer(a),"nonterminal original queue can admit a later event");dropped.clear(true);check(dropped.closed()&&!dropped.offer(b),"terminal original queue refuses later admission");check(CombatNpcDamageQueue.pending()==baseline,"clear paths release all original global queue slots");
  boolean monitor=false;try{NativeSourceCubeNpcQueue.clearing(new CombatNpcDamageQueue.Queue());}catch(IllegalStateException expected){monitor=true;}check(monitor,"typed drop hook requires original queue ownership");
  check(!NativeSourceCubeNpcQueue.before(null,0,null,0,0),"actual HP gate requires a queued and claimed original event");
  if(cases!=33)throw new AssertionError(cases);System.out.println("PASS33 pure shared-CAS/failed-publication/actual-unbound-FIFO/mixed-original-drainer/drop contracts; no player/Hub/socket/SQL/BATTLE fixture, no actual HP/Main qualification");
 }
}
